SELECT * FROM (
  SELECT deptno, job, sal FROM (
    SELECT 10 deptno, 'CLERK' job, 100 sal FROM DUAL UNION ALL
    SELECT 10 deptno, 'CLERK' job, 200 sal FROM DUAL UNION ALL
    SELECT 10 deptno, 'MANAGER' job, 300 sal FROM DUAL
  )
)
PIVOT (
  SUM(sal) FOR job IN ('CLERK' AS clerk, 'MANAGER' AS manager)
);
